INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c8813056-f446-5d07-bd3f-bd972f9b3ae7', 'ASEAN Green Bond Standards', 'ASEAN Green Bond Standards', 'The ASEAN Green Bonds Standards is an initiative that facilitates ASEAN capital markets in tapping green finance to support sustainable regional growth and meet investor interest for green investments and is part of the ACMF’s broader efforts in developing green finance for the region. The ASEAN Green Bond Standards have been developed in collaboration with the International Capital Market Association (ICMA) based on ICMA’s Green Bond Principles (GBP). The GBP have been used as the basis of the ASEAN Green Bond Standards as they are internationally accepted and widely used for the development of national green bond guidelines or standards issued globally.', 'The ASEAN Green Bonds Standards is an initiative that facilitates ASEAN capital markets in tapping green finance to support sustainable regional growth and meet investor interest for green investments and is part of the ACMF’s broader efforts in developing green finance for the region. The ASEAN Green Bond Standards have been developed in collaboration with the International Capital Market Association (ICMA) based on ICMA’s Green Bond Principles (GBP). The GBP have been used as the basis of the ASEAN Green Bond Standards as they are internationally accepted and widely used for the development of national green bond guidelines or standards issued globally.', 'The ASEAN Green Bonds Standards is an initiative that facilitates ASEAN capital markets in tapping green finance to support sustainable regional growth and meet investor interest for green investments and is part of the ACMF’s broader efforts in developing green finance for the region. The ASEAN Green Bond Standards have been developed in collaboration with the International Capital Market Association (ICMA) based on ICMA’s Green Bond Principles (GBP). The GBP have been used as the basis of the ASEAN Green Bond Standards as they are internationally accepted and widely used for the development of national green bond guidelines or standards issued globally.', 'ASEAN', 'climate', 'in_force', '2018-01-01'::date, 'ASEAN Capital Markets Forum', 'https://afcwp.asean.org/wp-content/uploads/2020/08/Agenda-Item-2.0-ASEAN-Green-Bond-Standards.pdf', ARRAY['sdg14', 'asean', 'sdg17', 'voluntary', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1dab4102-cac3-56e0-bf6a-0347123b58c5', 'ASEAN Sustainability Bond Standards', 'ASEAN Sustainability Bond Standards', 'The ASEAN Sustainability Bond Standards (ASEAN SUS) intend to provide guidance on the issuance of ASEAN Sustainability Bonds. ASEAN Sustainability Bonds are bonds where the proceeds will be exclusively applied to finance or re-finance a combination of both Green and Social Projects that respectively offer environmental and social benefits. It is understood that certain Green Projects may also have social co-benefits, and that certain Social Projects may have environmental co-benefits. The classification of a use of proceeds bond as a Green Bond, Social Bond, or Sustainability Bond should be determined by the Issuer based on its primary objectives for the underlying projects.', 'The ASEAN Sustainability Bond Standards (ASEAN SUS) intend to provide guidance on the issuance of ASEAN Sustainability Bonds. ASEAN Sustainability Bonds are bonds where the proceeds will be exclusively applied to finance or re-finance a combination of both Green and Social Projects that respectively offer environmental and social benefits. It is understood that certain Green Projects may also have social co-benefits, and that certain Social Projects may have environmental co-benefits. The classification of a use of proceeds bond as a Green Bond, Social Bond, or Sustainability Bond should be determined by the Issuer based on its primary objectives for the underlying projects.', 'The ASEAN Sustainability Bond Standards (ASEAN SUS) intend to provide guidance on the issuance of ASEAN Sustainability Bonds. ASEAN Sustainability Bonds are bonds where the proceeds will be exclusively applied to finance or re-finance a combination of both Green and Social Projects that respectively offer environmental and social benefits. It is understood that certain Green Projects may also have social co-benefits, and that certain Social Projects may have environmental co-benefits. The classification of a use of proceeds bond as a Green Bond, Social Bond, or Sustainability Bond should be determined by the Issuer based on its primary objectives for the underlying projects.', 'ASEAN', 'nature', 'in_force', '2018-01-01'::date, 'Climate Bonds Initiative', 'https://www.climatebonds.net/files/documents/publications/ASEAN-Green-Finance-State-of-the-Market-2018.pdf', ARRAY['voluntary_frameworks', 'sdg14', 'asean', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('67a0df83-8517-5e8d-b45d-1f6cca0987df', 'ASEAN Guidelines for Corporate Social Responsibility (CSR) on Labour', 'ASEAN Guidelines for Corporate Social Responsibility (CSR) on Labour', 'The ASEAN Guidelines for CSR on Labour were developed to promote ethical labor practices, social sustainability, and corporate accountability across ASEAN Member States. The guidelines align with ASEAN Vision 2025 and key international labor frameworks, including ILO Conventions, UN Guiding Principles on Business and Human Rights, and ISO 26000 on Social Responsibility.

Key provisions include:

CSR in Labour and Sustainable Development:
Encourages companies to implement responsible labor practices.
Aligns with ASEAN Economic, Political-Security, and Socio-Cultural Community Blueprints.
Labor Rights & Fair Employment Practices:
Prohibits forced labor and child labor in all forms.
Promotes fair wages, non-discrimination, and occupational health & safety standards.
Strengthens social dialogue between employers, workers, and governments.
Migrant Worker Protections:
Ensures fair treatment, equal wages, and access to labor rights.
Corporate Transparency & Accountability:
Companies must regularly report on CSR initiatives and progress.
Encourages businesses to adopt international labor reporting frameworks.
Environmental & Social Responsibility:
Promotes sustainable practices, waste management, and resource efficiency.
These guidelines promote responsible business conduct across ASEAN by ensuring fair labor practices and social protection for workers.', 'The ASEAN Guidelines for CSR on Labour were developed to promote ethical labor practices, social sustainability, and corporate accountability across ASEAN Member States. The guidelines align with ASEAN Vision 2025 and key international labor frameworks, including ILO Conventions, UN Guiding Principles on Business and Human Rights, and ISO 26000 on Social Responsibility.

