INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1fe23a50-ecd5-5a9c-ae1b-abffe28121ea', 'Regional Strategy on CSR and Human Rights in ASEAN', 'Regional Strategy on CSR and Human Rights in ASEAN', 'The document is based on internationally-accepted standards, particularly the UN Guiding Principles on Business and Human Rights (UNGPs), recognising the importance of a multi-stakeholder approach to achieving business and human rights in the region. The role of states, businesses, trade unions, civil society organisations and national human rights institutions are stated, in accordance with the 3 pillars of the UNGPs.', 'The document is based on internationally-accepted standards, particularly the UN Guiding Principles on Business and Human Rights (UNGPs), recognising the importance of a multi-stakeholder approach to achieving business and human rights in the region. The role of states, businesses, trade unions, civil society organisations and national human rights institutions are stated, in accordance with the 3 pillars of the UNGPs.', 'The document is based on internationally-accepted standards, particularly the UN Guiding Principles on Business and Human Rights (UNGPs), recognising the importance of a multi-stakeholder approach to achieving business and human rights in the region. The role of states, businesses, trade unions, civil society organisations and national human rights institutions are stated, in accordance with the 3 pillars of the UNGPs.', 'ASEAN', 'climate', 'in_force', '2017-01-01'::date, 'ASEAN CSR Network', 'https://www.asean-csr-network.org/c/images/RegionalStrategyonCSRandHumanRightsinASEANJune2017.pdf', ARRAY['sdg14', 'asean', 'other sustainability policy', 'sdg17', 'voluntary', 'sdg16', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6c2180d-b123-5f26-8d20-e386f874f4ff', 'Australia Taxation Administration Act', 'Taxation Administration Act 1953', 'The Taxation Administration Act 1953 in Australia governs tax administration processes, including reporting requirements for entities with specific income levels, digital invoicing, and tax offsets. Targeted at tax entities, this policy aims to ensure compliance and transparency in tax-related activities.', 'The Taxation Administration Act 1953 in Australia governs tax administration processes, including reporting requirements for entities with specific income levels, digital invoicing, and tax offsets. Targeted at tax entities, this policy aims to ensure compliance and transparency in tax-related activities.', 'The Taxation Administration Act 1953 in Australia governs tax administration processes, including reporting requirements for entities with specific income levels, digital invoicing, and tax offsets. Targeted at tax entities, this policy aims to ensure compliance and transparency in tax-related activities.', 'Australia', 'climate', 'in_force', '2025-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_90', ARRAY['sdg16', 'australia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('794fdab2-659d-582f-b298-7ced78d494d1', 'Australia PS LA 2025/2 - Public country-by-country reporting exemptions', 'PS LA 2025/2 - Public country-by-country reporting exemptions', 'PS LA 2025/2 guides Australian tax authorities on granting exemptions from public country-by-country reporting obligations for multinational entities. It outlines criteria, application process, and decision-making principles for exemption seekers, focusing on entities meeting specific financial thresholds and group structures. Target audience includes ATO staff handling exemption applications.', 'PS LA 2025/2 guides Australian tax authorities on granting exemptions from public country-by-country reporting obligations for multinational entities. It outlines criteria, application process, and decision-making principles for exemption seekers, focusing on entities meeting specific financial thresholds and group structures. Target audience includes ATO staff handling exemption applications.', 'PS LA 2025/2 guides Australian tax authorities on granting exemptions from public country-by-country reporting obligations for multinational entities. It outlines criteria, application process, and decision-making principles for exemption seekers, focusing on entities meeting specific financial thresholds and group structures. Target audience includes ATO staff handling exemption applications.', 'Australia', 'climate', 'in_force', '2025-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_91', ARRAY['australia', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('705ff7a9-3948-5077-85f3-2238a71b45e1', 'Australia Mandatory Climate-Related Financial Disclosures (ammendments to the Corporations', 'Mandatory Climate-Related Financial Disclosures (ammendments to the Corporations Act)', 'The 2024 update on mandatory climate-related financial disclosures introduces Australia’s requirements for large businesses and financial institutions to provide standardized sustainability reports, effective for financial years starting on or after January 1, 2025. These reports must comply with the Australian Sustainability Reporting Standards (ASRS), developed by the Australian Accounting Standards Board (AASB). The ASRS incorporates elements of global standards, such as IFRS S1 and IFRS S2, emphasizing transparency, comparability, and decision-useful information.

Key provisions include disclosures on governance, strategy, risk management, and metrics and targets, with a focus on climate resilience and greenhouse gas (GHG) emissions reporting (Scopes 1, 2, and 3). Entities are required to conduct scenario analyses, including one consistent with limiting warming to 1.5°C. Sustainability reports must be audited starting July 1, 2030, with phased assurance requirements preceding this date.

The framework applies to listed and unlisted entities meeting size thresholds, with specific guidelines for not-for-profits and inbound subsidiaries. ASIC will oversee compliance and provide guidance during implementation, including temporary liability relief for forward-looking disclosures.', 'The 2024 update on mandatory climate-related financial disclosures introduces Australia’s requirements for large businesses and financial institutions to provide standardized sustainability reports, effective for financial years starting on or after January 1, 2025. These reports must comply with the Australian Sustainability Reporting Standards (ASRS), developed by the Australian Accounting Standards Board (AASB). The ASRS incorporates elements of global standards, such as IFRS S1 and IFRS S2, emphasizing transparency, comparability, and decision-useful information.

Key provisions include disclosures on governance, strategy, risk management, and metrics and targets, with a focus on climate resilience and greenhouse gas (GHG) emissions reporting (Scopes 1, 2, and 3). Entities are required to conduct scenario analyses, including one consistent with limiting warming to 1.5°C. Sustainability reports must be audited starting July 1, 2030, with phased assurance requirements preceding this date.

The framework applies to listed and unlisted entities meeting size thresholds, with specific guidelines for not-for-profits and inbound subsidiaries. ASIC will oversee compliance and provide guidance during implementation, including temporary liability relief for forward-looking disclosures.', 'The 2024 update on mandatory climate-related financial disclosures introduces Australia’s requirements for large businesses and financial institutions to provide standardized sustainability reports, effective for financial years starting on or after January 1, 2025. These reports must comply with the Australian Sustainability Reporting Standards (ASRS), developed by the Australian Accounting Standards Board (AASB). The ASRS incorporates elements of global standards, such as IFRS S1 and IFRS S2, emphasizing transparency, comparability, and decision-useful information.

Key provisions include disclosures on governance, strategy, risk management, and metrics and targets, with a focus on climate resilience and greenhouse gas (GHG) emissions reporting (Scopes 1, 2, and 3). Entities are required to conduct scenario analyses, including one consistent with limiting warming to 1.5°C. Sustainability reports must be audited starting July 1, 2030, with phased assurance requirements preceding this date.

The framework applies to listed and unlisted entities meeting size thresholds, with specific guidelines for not-for-profits and inbound subsidiaries. ASIC will oversee compliance and provide guidance during implementation, including temporary liability relief for forward-looking disclosures.', 'Australia', 'climate', 'in_force', '2024-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_400', ARRAY['australia', 'sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('72f24e4d-777b-5ecc-b1a2-829ec0193e13', 'Australia director’s guide to mandatory climate reporting', 'A director’s guide to mandatory climate reporting, 2023', 'The director’s guide to mandatory climate reporting provides practical guidance to Australian directors to effectively oversee the transition to mandatory climate reporting.', 'The director’s guide to mandatory climate reporting provides practical guidance to Australian directors to effectively oversee the transition to mandatory climate reporting.', 'The director’s guide to mandatory climate reporting provides practical guidance to Australian directors to effectively oversee the transition to mandatory climate reporting.', 'Australia', 'climate', 'in_force', '2023-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_81', ARRAY['australia', 'sdg13', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9b18b4db-da0c-59e5-b22f-ba5a3fb6cc1b', 'ESG Reporting Standard for Australian Community Housing', 'An ESG Reporting Standard for Australian Community Housing', 'This report sets out the background and opportunities arising from the recently launched ESG standard for Australian community housing.', 'This report sets out the background and opportunities arising from the recently launched ESG standard for Australian community housing.', 'This report sets out the background and opportunities arising from the recently launched ESG standard for Australian community housing.', 'Australia', 'climate', 'in_force', '2023-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_83', ARRAY['australia', 'voluntary_frameworks', 'sdg11', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7746620f-2c9c-5350-83ee-b29212fa7d6b', 'Australia Environmental and sustainability claims. Draft guidance for business', 'Environmental and sustainability claims. Draft guidance for business', 'This draft guidance explains the obligations under the Australian Consumer Law (ACL) which businesses must comply with when making environmental and sustainability claims. It sets out what the ACCC considers to be good practice when making such claims, to help businesses provide clear, accurate and trustworthy information to consumers about the environmental performance of their business.', 'This draft guidance explains the obligations under the Australian Consumer Law (ACL) which businesses must comply with when making environmental and sustainability claims. It sets out what the ACCC considers to be good practice when making such claims, to help businesses provide clear, accurate and trustworthy information to consumers about the environmental performance of their business.', 'This draft guidance explains the obligations under the Australian Consumer Law (ACL) which businesses must comply with when making environmental and sustainability claims. It sets out what the ACCC considers to be good practice when making such claims, to help businesses provide clear, accurate and trustworthy information to consumers about the environmental performance of their business.', 'Australia', 'governance', 'in_force', '2023-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_84', ARRAY['australia', 'guidance_frameworks', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0c54a882-3bb1-57f0-bf44-fc66266f8ffa', 'Review of Australia''s Modern Slavery Act. Issue Paper', 'Review of Australia''s Modern Slavery Act. Issue Paper', 'The Australian Modern Slavery Act 2018 requires a review to be undertaken three years after its commencement, with the report to be tabled in Parliament. The review was announced in March 2022 and is being led by Professor John McMillan AO, with the objective of considering the Act''s operation over the first three years and options for improved operation and compliance. The review will consider both the terms of the Act and its administrative implementation, with specific features such as reporting thresholds, reporting criteria, enforcement mechanisms, and the option of establishing an independent Anti-Slavery Commissioner mentioned in the terms of reference. The review will be conducted in an open, transparent, and consultative manner through written submissions, targeted consultations, and a survey of entities reporting under the Act, with the review team consulting widely and responding to consultation invitations.', 'The Australian Modern Slavery Act 2018 requires a review to be undertaken three years after its commencement, with the report to be tabled in Parliament. The review was announced in March 2022 and is being led by Professor John McMillan AO, with the objective of considering the Act''s operation over the first three years and options for improved operation and compliance. The review will consider both the terms of the Act and its administrative implementation, with specific features such as reporting thresholds, reporting criteria, enforcement mechanisms, and the option of establishing an independent Anti-Slavery Commissioner mentioned in the terms of reference. The review will be conducted in an open, transparent, and consultative manner through written submissions, targeted consultations, and a survey of entities reporting under the Act, with the review team consulting widely and responding to consultation invitations.', 'The Australian Modern Slavery Act 2018 requires a review to be undertaken three years after its commencement, with the report to be tabled in Parliament. The review was announced in March 2022 and is being led by Professor John McMillan AO, with the objective of considering the Act''s operation over the first three years and options for improved operation and compliance. The review will consider both the terms of the Act and its administrative implementation, with specific features such as reporting thresholds, reporting criteria, enforcement mechanisms, and the option of establishing an independent Anti-Slavery Commissioner mentioned in the terms of reference. The review will be conducted in an open, transparent, and consultative manner through written submissions, targeted consultations, and a survey of entities reporting under the Act, with the review team consulting widely and responding to consultation invitations.', 'Australia', 'climate', 'in_force', '2022-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_74', ARRAY['australia', 'sdg8', 'regulations', 'mandatory', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06c915ce-5282-5dbb-bca1-e5f4db0af888', 'Australia Sheep Sustainability Framework. Strategic Plan FY2022-FY', 'Sheep Sustainability Framework. Strategic Plan FY2022-FY2024', 'The sustainable production of sheep meat and wool is important for gaining access to local and global markets. The Sheep Producers Australia and Wool Producers Australia are leading a Framework to measure and monitor the industry''s performance in animal care, the environment, economic resilience, and people and community. The goal is to demonstrate that Australia is a global leader in sustainable sheep production and ensure continued market access. The Framework does not set policies, goals, or targets, but focuses on on-farm, transport, saleyards, and Australian processors, with plans to extend to the overseas wool processing sector in the future.', 'The sustainable production of sheep meat and wool is important for gaining access to local and global markets. The Sheep Producers Australia and Wool Producers Australia are leading a Framework to measure and monitor the industry''s performance in animal care, the environment, economic resilience, and people and community. The goal is to demonstrate that Australia is a global leader in sustainable sheep production and ensure continued market access. The Framework does not set policies, goals, or targets, but focuses on on-farm, transport, saleyards, and Australian processors, with plans to extend to the overseas wool processing sector in the future.', 'The sustainable production of sheep meat and wool is important for gaining access to local and global markets. The Sheep Producers Australia and Wool Producers Australia are leading a Framework to measure and monitor the industry''s performance in animal care, the environment, economic resilience, and people and community. The goal is to demonstrate that Australia is a global leader in sustainable sheep production and ensure continued market access. The Framework does not set policies, goals, or targets, but focuses on on-farm, transport, saleyards, and Australian processors, with plans to extend to the overseas wool processing sector in the future.', 'Australia', 'climate', 'in_force', '2022-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_76', ARRAY['australia', 'sdg2', 'sdg14', 'sdg11', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d61c784-fa1d-51d0-8cbd-55851e78a001', 'Australia Building a better future. Budget October', 'Building a better future. Budget October 2022-23', 'The Australian Budget for 2022-23 focuses on building a better future through measures aimed at supporting businesses and promoting sustainability. The budget includes initiatives such as tax incentives for small and medium-sized businesses, funding for infrastructure projects, and investments in clean energy technologies. The government has also announced a plan to reduce emissions and meet its climate targets, with a focus on supporting farmers and regional communities to adopt sustainable practices. In addition, the budget includes measures to improve the quality of education and training, increase access to affordable housing, and support research and development in emerging industries.', 'The Australian Budget for 2022-23 focuses on building a better future through measures aimed at supporting businesses and promoting sustainability. The budget includes initiatives such as tax incentives for small and medium-sized businesses, funding for infrastructure projects, and investments in clean energy technologies. The government has also announced a plan to reduce emissions and meet its climate targets, with a focus on supporting farmers and regional communities to adopt sustainable practices. In addition, the budget includes measures to improve the quality of education and training, increase access to affordable housing, and support research and development in emerging industries.', 'The Australian Budget for 2022-23 focuses on building a better future through measures aimed at supporting businesses and promoting sustainability. The budget includes initiatives such as tax incentives for small and medium-sized businesses, funding for infrastructure projects, and investments in clean energy technologies. The government has also announced a plan to reduce emissions and meet its climate targets, with a focus on supporting farmers and regional communities to adopt sustainable practices. In addition, the budget includes measures to improve the quality of education and training, increase access to affordable housing, and support research and development in emerging industries.', 'Australia', 'climate', 'in_force', '2022-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_78', ARRAY['sdg4', 'australia', 'sdg13', 'other sustainability policy', 'sdg2', 'regulations', 'sdg7', 'mandatory', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7db7bad8-79ec-51ed-bd50-b1053fa88679', 'Building a more circular Australia. The opportunity', 'Building a more circular Australia. The opportunity of transitioning to a circular economy', 'In this report, we explore the opportunity for Australia to adopt the concept of a circular economy, establishing a robust and holistic framework for sustainable growth. This involves creating closed-loop material cycles across the production and consumption value chain, and treating waste as a leakage of value to be avoided rather than dismissed.', 'In this report, we explore the opportunity for Australia to adopt the concept of a circular economy, establishing a robust and holistic framework for sustainable growth. This involves creating closed-loop material cycles across the production and consumption value chain, and treating waste as a leakage of value to be avoided rather than dismissed.', 'In this report, we explore the opportunity for Australia to adopt the concept of a circular economy, establishing a robust and holistic framework for sustainable growth. This involves creating closed-loop material cycles across the production and consumption value chain, and treating waste as a leakage of value to be avoided rather than dismissed.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_44', ARRAY['australia', 'other sustainability policy', 'sdg11', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a3a33f8d-d08f-53f4-9634-dbb660a97464', 'Australia Effective modern slavery grievance mechanisms: A case study', 'Effective modern slavery grievance mechanisms: A case study publication for business', 'This report aims to support businesses to better understand how they can effectively address and report on modern slavery risks by building practical knowledge about the role and function of effective grievance mechanisms.', 'This report aims to support businesses to better understand how they can effectively address and report on modern slavery risks by building practical knowledge about the role and function of effective grievance mechanisms.', 'This report aims to support businesses to better understand how they can effectively address and report on modern slavery risks by building practical knowledge about the role and function of effective grievance mechanisms.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_54', ARRAY['australia', 'sdg8', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dd7b53b1-9d2d-5dff-a2d8-5f447edcfa21', 'Australia Ensuring quality control and safety in insulation installation', 'Ensuring quality control and safety in insulation installation. A research report to support an industry-led roadmap for healthy, comfortable buildings', 'This Research Report sets out the findings and recommendations of the Project Team to ensure that insulation is installed following appropriate quality-control and safety processes. The Research Report will be used to inform the development of a short ‘Industry-led Insulation Roadmap’ that aims to facilitate actions from industry, government and the community that will ensure that insulation is installed following appropriate quality-control and safety processes.', 'This Research Report sets out the findings and recommendations of the Project Team to ensure that insulation is installed following appropriate quality-control and safety processes. The Research Report will be used to inform the development of a short ‘Industry-led Insulation Roadmap’ that aims to facilitate actions from industry, government and the community that will ensure that insulation is installed following appropriate quality-control and safety processes.', 'This Research Report sets out the findings and recommendations of the Project Team to ensure that insulation is installed following appropriate quality-control and safety processes. The Research Report will be used to inform the development of a short ‘Industry-led Insulation Roadmap’ that aims to facilitate actions from industry, government and the community that will ensure that insulation is installed following appropriate quality-control and safety processes.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_55', ARRAY['australia', 'sdg14', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('814db16b-cd41-504a-a8da-f15c35d9950e', 'Australia Financial services and modern slavery. Practical responses', 'Financial services and modern slavery. Practical responses for managing risk to people', 'This instrument is a guide to help the financial services industry respond effectively to the Modern Slavery Act 2018 (Cth). The Act requires certain large companies to report annually on their efforts to address risks of modern slavery in their global operations and supply chains.', 'This instrument is a guide to help the financial services industry respond effectively to the Modern Slavery Act 2018 (Cth). The Act requires certain large companies to report annually on their efforts to address risks of modern slavery in their global operations and supply chains.', 'This instrument is a guide to help the financial services industry respond effectively to the Modern Slavery Act 2018 (Cth). The Act requires certain large companies to report annually on their efforts to address risks of modern slavery in their global operations and supply chains.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_57', ARRAY['australia', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b3106b41-3909-5481-b659-c76a1cf1ddbf', 'Australia Prudential practice guide: Draft CPG 229 climate change', 'Prudential practice guide: Draft CPG 229 climate change financial risks', 'This PPG aims to assist an APRA-regulated institution in complying with Prudential Standards CPS 220 Risk Management (CPS 220), SPS 220 Risk Management (SPS 220), CPS 510 Governance (CPS 510), SPS 510 Governance (SPS 510) and, more generally, to outline prudent practices in relation to climate change financial risk management.', 'This PPG aims to assist an APRA-regulated institution in complying with Prudential Standards CPS 220 Risk Management (CPS 220), SPS 220 Risk Management (SPS 220), CPS 510 Governance (CPS 510), SPS 510 Governance (SPS 510) and, more generally, to outline prudent practices in relation to climate change financial risk management.', 'This PPG aims to assist an APRA-regulated institution in complying with Prudential Standards CPS 220 Risk Management (CPS 220), SPS 220 Risk Management (SPS 220), CPS 510 Governance (CPS 510), SPS 510 Governance (SPS 510) and, more generally, to outline prudent practices in relation to climate change financial risk management.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_60', ARRAY['australia', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bdbc48c-fc11-5c0f-9ca7-cf7e13b70aaf', 'Australia National Plastics Plan', 'National Plastics Plan 2021', 'The National Plastic Plan outlines the Department of Agriculture, Water and the Environment’s approach to increase plastic recycling, find alternatives to unnecessary plastics and reduce the impact of plastic on the environment.', 'The National Plastic Plan outlines the Department of Agriculture, Water and the Environment’s approach to increase plastic recycling, find alternatives to unnecessary plastics and reduce the impact of plastic on the environment.', 'The National Plastic Plan outlines the Department of Agriculture, Water and the Environment’s approach to increase plastic recycling, find alternatives to unnecessary plastics and reduce the impact of plastic on the environment.', 'Australia', 'nature', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_63', ARRAY['australia', 'sdg2', 'other sustainability policy', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42a2787f-dbe3-56e4-8398-432982e7fcbe', 'Australia Implementing Effective Modern Slavery Grievance Mechanisms. A Guidance', 'Implementing Effective Modern Slavery Grievance Mechanisms. A Guidance Note for Business', 'This instrument provides practical advice, flags key considerations, and outlines good practice steps for designing and implementing effective grievance mechanisms. The publication series supports business to know how to better hear and address instances of modern slavery.', 'This instrument provides practical advice, flags key considerations, and outlines good practice steps for designing and implementing effective grievance mechanisms. The publication series supports business to know how to better hear and address instances of modern slavery.', 'This instrument provides practical advice, flags key considerations, and outlines good practice steps for designing and implementing effective grievance mechanisms. The publication series supports business to know how to better hear and address instances of modern slavery.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_67', ARRAY['australia', 'guidance_frameworks', 'sdg8', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba2daa83-0dcc-5bf4-b494-e65bb65c44dc', 'Australia Moving from paper to practice: ASX200 reporting under', 'Moving from paper to practice: ASX200 reporting under Australia’s Modern Slavery Act', 'Until recently, there was no legal requirement for businesses to assess and address modern slavery risks in their operations and supply chain. The Modern Slavery Act (2018) now requires companies with revenue of over AUD$100M to publicly disclose their exposure to modern slavery risks. This has been published as complimentary guidance to the Australian Anti-Slavery bill which was passed in 2021.', 'Until recently, there was no legal requirement for businesses to assess and address modern slavery risks in their operations and supply chain. The Modern Slavery Act (2018) now requires companies with revenue of over AUD$100M to publicly disclose their exposure to modern slavery risks. This has been published as complimentary guidance to the Australian Anti-Slavery bill which was passed in 2021.', 'Until recently, there was no legal requirement for businesses to assess and address modern slavery risks in their operations and supply chain. The Modern Slavery Act (2018) now requires companies with revenue of over AUD$100M to publicly disclose their exposure to modern slavery risks. This has been published as complimentary guidance to the Australian Anti-Slavery bill which was passed in 2021.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_75', ARRAY['australia', 'sdg8', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('756dfa0f-4bd3-5aa7-8454-9cea608ec0a5', 'Australia Council of Financial Regulators Climate Change Activity Stocktake', 'Council of Financial Regulators Climate Change Activity Stocktake 2021', 'This stocktake paper outlines the recent activities and planned further work of the Council of Financial Regulators Working Group on Financial Implications of Climate Change in relation to climate change risks. The CFR agencies in Australia are taking steps to help corporates and financial institutions manage the financial risks associated with climate change and provide comparable disclosures on these risks. The Climate Vulnerability Assessment (CVA) conducted by APRA on behalf of other CFR agencies in 2020/21 measures potential financial risks posed by both physical and transition climate risks using scenario analysis, and aims to improve banks'' climate risk management capabilities. The CFR agencies are also building their understanding and knowledge about how to measure and manage climate-related risks through supervisory and regulatory engagement, collaboration with expert bodies, and participation in international forums where climate change issues are gaining increasing prominence.', 'This stocktake paper outlines the recent activities and planned further work of the Council of Financial Regulators Working Group on Financial Implications of Climate Change in relation to climate change risks. The CFR agencies in Australia are taking steps to help corporates and financial institutions manage the financial risks associated with climate change and provide comparable disclosures on these risks. The Climate Vulnerability Assessment (CVA) conducted by APRA on behalf of other CFR agencies in 2020/21 measures potential financial risks posed by both physical and transition climate risks using scenario analysis, and aims to improve banks'' climate risk management capabilities. The CFR agencies are also building their understanding and knowledge about how to measure and manage climate-related risks through supervisory and regulatory engagement, collaboration with expert bodies, and participation in international forums where climate change issues are gaining increasing prominence.', 'This stocktake paper outlines the recent activities and planned further work of the Council of Financial Regulators Working Group on Financial Implications of Climate Change in relation to climate change risks. The CFR agencies in Australia are taking steps to help corporates and financial institutions manage the financial risks associated with climate change and provide comparable disclosures on these risks. The Climate Vulnerability Assessment (CVA) conducted by APRA on behalf of other CFR agencies in 2020/21 measures potential financial risks posed by both physical and transition climate risks using scenario analysis, and aims to improve banks'' climate risk management capabilities. The CFR agencies are also building their understanding and knowledge about how to measure and manage climate-related risks through supervisory and regulatory engagement, collaboration with expert bodies, and participation in international forums where climate change issues are gaining increasing prominence.', 'Australia', 'climate', 'in_force', '2021-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_77', ARRAY['australia', 'sdg13', 'regulations', 'sdg17', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('afc0ca8a-2e45-554d-93b6-19270b15b56a', 'Climate disclosures within the Annual Report. An Australian Focus', 'Climate disclosures within the Annual Report. An Australian Focus', 'This report is a guide to help businesses communicate the impacts of climate on their business models, strategy, financial performance, and future prospects in their Annual Reports and Financial Statements. It will help you navigate the different disclosure requirements and recommendations applicable in Australia that may be impacted by climate risks.', 'This report is a guide to help businesses communicate the impacts of climate on their business models, strategy, financial performance, and future prospects in their Annual Reports and Financial Statements. It will help you navigate the different disclosure requirements and recommendations applicable in Australia that may be impacted by climate risks.', 'This report is a guide to help businesses communicate the impacts of climate on their business models, strategy, financial performance, and future prospects in their Annual Reports and Financial Statements. It will help you navigate the different disclosure requirements and recommendations applicable in Australia that may be impacted by climate risks.', 'Australia', 'climate', 'in_force', '2020-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_48', ARRAY['australia', 'sdg13', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc28d96e-1412-5467-afc3-3ac07415619d', 'Australia Climate change risk disclosure: A practical guide', 'Climate change risk disclosure: A practical guide to reporting against ASX Corporate Governance Council’s Corporate Governance Principles and Recommendations', 'The 4th edition of the ASX Corporate Governance Council’s: Corporate Governance Principles and Recommendations explicitly encourages entities to consider whether they have material exposure to climate change by reference to the Task Force on Climate-related Financial Disclosure Recommendations (TCFD). If an organisation does, then disclosures outlined by the TCFD are recommended. This is a critical guide to disclosing climate change risk and is relevant to any organisation – listed, non-listed or not-for-profit.', 'The 4th edition of the ASX Corporate Governance Council’s: Corporate Governance Principles and Recommendations explicitly encourages entities to consider whether they have material exposure to climate change by reference to the Task Force on Climate-related Financial Disclosure Recommendations (TCFD). If an organisation does, then disclosures outlined by the TCFD are recommended. This is a critical guide to disclosing climate change risk and is relevant to any organisation – listed, non-listed or not-for-profit.', 'The 4th edition of the ASX Corporate Governance Council’s: Corporate Governance Principles and Recommendations explicitly encourages entities to consider whether they have material exposure to climate change by reference to the Task Force on Climate-related Financial Disclosure Recommendations (TCFD). If an organisation does, then disclosures outlined by the TCFD are recommended. This is a critical guide to disclosing climate change risk and is relevant to any organisation – listed, non-listed or not-for-profit.', 'Australia', 'climate', 'in_force', '2020-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_49', ARRAY['australia', 'sdg13', 'regulations', 'sdg7', 'sdg16', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2773768b-252e-530b-a1bc-e235bb8ac05e', 'Australia Recycling and Waste Reduction Act', 'Recycling and Waste Reduction Act. No. 119, 2020', 'This bill establishes a framework to: regulate the export of waste materials, in line with the agreement to ban the export of waste plastic, paper, glass and tyres by the Council of Australian Governments in 2020; manage the environmental, health and safety impacts of products, in particular those impacts associated with the disposal of products; and provide for voluntary, co-regulatory and mandatory product stewardship schemes.', 'This bill establishes a framework to: regulate the export of waste materials, in line with the agreement to ban the export of waste plastic, paper, glass and tyres by the Council of Australian Governments in 2020; manage the environmental, health and safety impacts of products, in particular those impacts associated with the disposal of products; and provide for voluntary, co-regulatory and mandatory product stewardship schemes.', 'This bill establishes a framework to: regulate the export of waste materials, in line with the agreement to ban the export of waste plastic, paper, glass and tyres by the Council of Australian Governments in 2020; manage the environmental, health and safety impacts of products, in particular those impacts associated with the disposal of products; and provide for voluntary, co-regulatory and mandatory product stewardship schemes.', 'Australia', 'climate', 'in_force', '2020-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_59', ARRAY['australia', 'sdg2', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e030461c-737b-5613-89fe-4b7cca81ecfb', 'Australia Growth through transformation: an investment vision guide', 'Growth through transformation: an investment vision guide for climate and development', 'This Guide outlines a five-part process to create an enabling environment for green investment and to align public and private sector finance with sustainable development and the goals of the Paris Agreement. As countries recover from the COVID-19 pandemic, the need to unlock investment is even more acute. For developing countries, enhancing attractiveness for international and private finance will be critical to their economic recovery. Ensuring this investment is aligned to climate and development goals can fast track the transition towards green growth. The guide presents a theoretical framework to complement efforts by countries to implement the long-term strategies developed under the Paris Agreement.', 'This Guide outlines a five-part process to create an enabling environment for green investment and to align public and private sector finance with sustainable development and the goals of the Paris Agreement. As countries recover from the COVID-19 pandemic, the need to unlock investment is even more acute. For developing countries, enhancing attractiveness for international and private finance will be critical to their economic recovery. Ensuring this investment is aligned to climate and development goals can fast track the transition towards green growth. The guide presents a theoretical framework to complement efforts by countries to implement the long-term strategies developed under the Paris Agreement.', 'This Guide outlines a five-part process to create an enabling environment for green investment and to align public and private sector finance with sustainable development and the goals of the Paris Agreement. As countries recover from the COVID-19 pandemic, the need to unlock investment is even more acute. For developing countries, enhancing attractiveness for international and private finance will be critical to their economic recovery. Ensuring this investment is aligned to climate and development goals can fast track the transition towards green growth. The guide presents a theoretical framework to complement efforts by countries to implement the long-term strategies developed under the Paris Agreement.', 'Australia', 'climate', 'in_force', '2020-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_71', ARRAY['australia', 'sdg13', 'regulations', 'sdg7', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e4ce8a0-e431-5956-8e76-7129fea5b519', 'Australia Climate Measurement Standards Initiative Scenario analysis of climate-related', 'Climate Measurement Standards Initiative Scenario analysis of climate-related physical risk for buildings and infrastructure: Climate science guidance', 'To determine the physical risks in a credible and comparable way, Australian companies need reliable information for scenario analyses. The Climate Measurement Standards Initiative (CMSI) is an industry-led collaboration between Australian insurers, banks, scientists, reporting standards professionals, service providers and supporting parties to assist with TCFD reporting. The CMSI is initially developing technical, business and scientific standards for climate-related physical risk to buildings and infrastructure assets. This is a technical summary of the report ‘Scenario analysis of climate-related physical risk for buildings and infrastructure: climate science guidance’. The report, which was independently authored by the Earth Systems and Climate Change Hub of the National Environmental Science Program (NESP), describes methods, scenarios for acute and chronic climate hazards, gaps and needs, and a roadmap for the future.', 'To determine the physical risks in a credible and comparable way, Australian companies need reliable information for scenario analyses. The Climate Measurement Standards Initiative (CMSI) is an industry-led collaboration between Australian insurers, banks, scientists, reporting standards professionals, service providers and supporting parties to assist with TCFD reporting. The CMSI is initially developing technical, business and scientific standards for climate-related physical risk to buildings and infrastructure assets. This is a technical summary of the report ‘Scenario analysis of climate-related physical risk for buildings and infrastructure: climate science guidance’. The report, which was independently authored by the Earth Systems and Climate Change Hub of the National Environmental Science Program (NESP), describes methods, scenarios for acute and chronic climate hazards, gaps and needs, and a roadmap for the future.', 'To determine the physical risks in a credible and comparable way, Australian companies need reliable information for scenario analyses. The Climate Measurement Standards Initiative (CMSI) is an industry-led collaboration between Australian insurers, banks, scientists, reporting standards professionals, service providers and supporting parties to assist with TCFD reporting. The CMSI is initially developing technical, business and scientific standards for climate-related physical risk to buildings and infrastructure assets. This is a technical summary of the report ‘Scenario analysis of climate-related physical risk for buildings and infrastructure: climate science guidance’. The report, which was independently authored by the Earth Systems and Climate Change Hub of the National Environmental Science Program (NESP), describes methods, scenarios for acute and chronic climate hazards, gaps and needs, and a roadmap for the future.', 'Australia', 'climate', 'in_force', '2020-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_73', ARRAY['australia', 'sdg13', 'other sustainability policy', 'sdg17', 'voluntary', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cce53a30-634f-5520-8f68-ebc68a57a125', 'Australia Corporate Governance Principles and Recommendations', 'Corporate Governance Principles and Recommendations: 4th edition, 2019', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'Australia', 'governance', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_15', ARRAY['australia', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9f2c8d86-232a-50e2-8788-d1b785ca7091', 'Australia Are you prepared for the increasing investor scrutiny', 'Are you prepared for the increasing investor scrutiny on climate risk disclosures? Climate Risk Disclosure Barometer: Australia 2019', 'The Climate Risk Disclosure Barometer: Australia 2019 charts how Australian organisations align with the Task Force on Climate-related Financial Disclosures.', 'The Climate Risk Disclosure Barometer: Australia 2019 charts how Australian organisations align with the Task Force on Climate-related Financial Disclosures.', 'The Climate Risk Disclosure Barometer: Australia 2019 charts how Australian organisations align with the Task Force on Climate-related Financial Disclosures.', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_42', ARRAY['australia', 'sdg13', 'sdg2', 'sdg9', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c2d50d7-665a-5390-a2ba-28447415de37', 'Australia Climate change and directors’ duties. Supplementary memorandum of', 'Climate change and directors’ duties. Supplementary memorandum of opinion', 'An opinion considering the extent to which the duty of care and diligence imposed upon company directors by s 180(1) of the Corporations Act 2001 (Cth) (“the Act”) permitted or required Australian company directors to respond to climate change risks.', 'An opinion considering the extent to which the duty of care and diligence imposed upon company directors by s 180(1) of the Corporations Act 2001 (Cth) (“the Act”) permitted or required Australian company directors to respond to climate change risks.', 'An opinion considering the extent to which the duty of care and diligence imposed upon company directors by s 180(1) of the Corporations Act 2001 (Cth) (“the Act”) permitted or required Australian company directors to respond to climate change risks.', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_47', ARRAY['australia', 'sdg13', 'sdg2', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6f80bf11-7557-58fe-b983-f7ea793c8cb5', 'Australia Information Paper. Climate Change: Awareness to action', 'Information Paper. Climate Change: Awareness to action', 'The Australian Prudential Regulation Authority''s (APRA) climate change survey of 38 large entities, across all regulated industries, highlights the range of activities and strategic responses that entities are adopting to assess and mitigate climate change risks. This Information Paper provides insights into the responses to APRA’s survey. Regulated entities may compare the results with their own operations and assess their responses to climate change financial risks.', 'The Australian Prudential Regulation Authority''s (APRA) climate change survey of 38 large entities, across all regulated industries, highlights the range of activities and strategic responses that entities are adopting to assess and mitigate climate change risks. This Information Paper provides insights into the responses to APRA’s survey. Regulated entities may compare the results with their own operations and assess their responses to climate change financial risks.', 'The Australian Prudential Regulation Authority''s (APRA) climate change survey of 38 large entities, across all regulated industries, highlights the range of activities and strategic responses that entities are adopting to assess and mitigate climate change risks. This Information Paper provides insights into the responses to APRA’s survey. Regulated entities may compare the results with their own operations and assess their responses to climate change financial risks.', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_50', ARRAY['australia', 'sdg13', 'regulations', 'mandatory', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d5194495-acf9-5f8b-8db6-8a9660a71560', 'Australia Climate-related and other emerging risks disclosures: assessing financial', 'Climate-related and other emerging risks disclosures: assessing financial statement materiality using AASB/IASB Practice Statement 2', 'This publication argues that climate-related risks and other emerging risks are currently predominantly discussed outside the financial statements, if at all, while qualitative external factors such as the industry in which the entity operates, and investor expectations may make such risks ‘material’ and warrant disclosures when preparing financial statements, regardless of their numerical impact. It also notes investor statements on the importance of climate-related risks to their decision making so that entities can no longer treat climate-related risks as merely a matter of corporate social responsibility and should consider them also in the context of their financial statement.', 'This publication argues that climate-related risks and other emerging risks are currently predominantly discussed outside the financial statements, if at all, while qualitative external factors such as the industry in which the entity operates, and investor expectations may make such risks ‘material’ and warrant disclosures when preparing financial statements, regardless of their numerical impact. It also notes investor statements on the importance of climate-related risks to their decision making so that entities can no longer treat climate-related risks as merely a matter of corporate social responsibility and should consider them also in the context of their financial statement.', 'This publication argues that climate-related risks and other emerging risks are currently predominantly discussed outside the financial statements, if at all, while qualitative external factors such as the industry in which the entity operates, and investor expectations may make such risks ‘material’ and warrant disclosures when preparing financial statements, regardless of their numerical impact. It also notes investor statements on the importance of climate-related risks to their decision making so that entities can no longer treat climate-related risks as merely a matter of corporate social responsibility and should consider them also in the context of their financial statement.', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_52', ARRAY['australia', 'sdg13', 'regulations', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a8d0f03e-638c-5ae5-92e6-65bc8520a094', 'Australia Financial Stability Review', 'Financial Stability Review 2019', 'The Financial Stability Review provides the Bank''s assessment of the current condition of the financial system and potential risks to financial stability.', 'The Financial Stability Review provides the Bank''s assessment of the current condition of the financial system and potential risks to financial stability.', 'The Financial Stability Review provides the Bank''s assessment of the current condition of the financial system and potential risks to financial stability.', 'Australia', 'nature', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_58', ARRAY['australia', 'sdg2', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7fb548e2-ebc3-5a30-96f9-da4887428f4d', 'Australia National Waste Policy Action Plan', 'National Waste Policy Action Plan', 'The National Waste Policy provides a national framework for waste and resource recovery in Australia. It outlines roles and responsibilities for collective action by businesses, governments, communities, and individuals.', 'The National Waste Policy provides a national framework for waste and resource recovery in Australia. It outlines roles and responsibilities for collective action by businesses, governments, communities, and individuals.', 'The National Waste Policy provides a national framework for waste and resource recovery in Australia. It outlines roles and responsibilities for collective action by businesses, governments, communities, and individuals.', 'Australia', 'circularity', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_61', ARRAY['australia', 'other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('16a34882-60d9-5103-b2e8-cf3a7010297d', 'Australia Modern Slavery Risks, Rights and Responsibilities. A Guide', 'Modern Slavery Risks, Rights and Responsibilities. A Guide for Companies and Investors', 'This report aims to increase the Australian business community’s understanding of modern slavery risks in their operations and supply chains, and to help prepare businesses to meet new regulatory requirements for transparent public disclosure.', 'This report aims to increase the Australian business community’s understanding of modern slavery risks in their operations and supply chains, and to help prepare businesses to meet new regulatory requirements for transparent public disclosure.', 'This report aims to increase the Australian business community’s understanding of modern slavery risks in their operations and supply chains, and to help prepare businesses to meet new regulatory requirements for transparent public disclosure.', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_65', ARRAY['australia', 'sdg8', 'sdg11', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d7b610a-657e-5e3b-aaa4-1efc87718c5a', 'Australia Modern Slavery Reporting - Guide for Investors', 'Modern Slavery Reporting - Guide for Investors', 'This guide has been prepared by ACSI and RIAA to provide a framework for investor reporting. It provides broad context on matters investors may wish to consider in preparing their modern slavery statements and should be used in conjunction with the guidance provided by the Australian Border Force (Government Guidance).', 'This guide has been prepared by ACSI and RIAA to provide a framework for investor reporting. It provides broad context on matters investors may wish to consider in preparing their modern slavery statements and should be used in conjunction with the guidance provided by the Australian Border Force (Government Guidance).', 'This guide has been prepared by ACSI and RIAA to provide a framework for investor reporting. It provides broad context on matters investors may wish to consider in preparing their modern slavery statements and should be used in conjunction with the guidance provided by the Australian Border Force (Government Guidance).', 'Australia', 'climate', 'in_force', '2019-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_66', ARRAY['australia', 'sdg8', 'sdg7', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4ca5c1d7-4876-52b3-ae17-d912d4bd0296', 'Australian Asset Owner Stewardship Code', 'Australian Asset Owner Stewardship Code, 2018', 'This Code raises the bar on signatories to proactively manage their stewardship activities. To encourage transparency and accountability, disclosure and reporting requirements are embedded in the Code.', 'This Code raises the bar on signatories to proactively manage their stewardship activities. To encourage transparency and accountability, disclosure and reporting requirements are embedded in the Code.', 'This Code raises the bar on signatories to proactively manage their stewardship activities. To encourage transparency and accountability, disclosure and reporting requirements are embedded in the Code.', 'Australia', 'climate', 'in_force', '2018-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_16', ARRAY['australia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('25d3b78d-1a92-5eab-9c32-484676975b8a', 'Australia Modern Slavery Act', 'Modern Slavery Act, 2018', 'The objects of this Act are as follows: (a) to combat modern slavery, (b) to provide assistance and support for victims of modern slavery, (c) to provide for an Anti-slavery Commissioner, (d) to provide for detection and exposure of modern slavery that may have occurred or be occurring or that is likely to occur, (e) to raise community awareness of, and provide for education and training about, modern slavery, (f) to encourage collaborative action to combat modern slavery, (g) to provide for the assessment of the effectiveness and appropriateness of laws prohibiting modern slavery and to improve the implementation and enforcement of such laws, (h) to provide for mandatory reporting of risks of modern slavery occurring in the supply chains of government agencies and commercial organisations, (i) to make forced marriage of a child and certain slavery and slavery-like conduct offences in New South Wales, (j) to further penalise involvement in cybersex trafficking by making it an offence to administer a digital platform for the purpose of child abuse material.', 'The objects of this Act are as follows: (a) to combat modern slavery, (b) to provide assistance and support for victims of modern slavery, (c) to provide for an Anti-slavery Commissioner, (d) to provide for detection and exposure of modern slavery that may have occurred or be occurring or that is likely to occur, (e) to raise community awareness of, and provide for education and training about, modern slavery, (f) to encourage collaborative action to combat modern slavery, (g) to provide for the assessment of the effectiveness and appropriateness of laws prohibiting modern slavery and to improve the implementation and enforcement of such laws, (h) to provide for mandatory reporting of risks of modern slavery occurring in the supply chains of government agencies and commercial organisations, (i) to make forced marriage of a child and certain slavery and slavery-like conduct offences in New South Wales, (j) to further penalise involvement in cybersex trafficking by making it an offence to administer a digital platform for the purpose of child abuse material.', 'The objects of this Act are as follows: (a) to combat modern slavery, (b) to provide assistance and support for victims of modern slavery, (c) to provide for an Anti-slavery Commissioner, (d) to provide for detection and exposure of modern slavery that may have occurred or be occurring or that is likely to occur, (e) to raise community awareness of, and provide for education and training about, modern slavery, (f) to encourage collaborative action to combat modern slavery, (g) to provide for the assessment of the effectiveness and appropriateness of laws prohibiting modern slavery and to improve the implementation and enforcement of such laws, (h) to provide for mandatory reporting of risks of modern slavery occurring in the supply chains of government agencies and commercial organisations, (i) to make forced marriage of a child and certain slavery and slavery-like conduct offences in New South Wales, (j) to further penalise involvement in cybersex trafficking by making it an offence to administer a digital platform for the purpose of child abuse material.', 'Australia', 'climate', 'in_force', '2018-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_19', ARRAY['sdg4', 'australia', 'sdg8', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e2e2fa0-2189-54c1-a8d7-272d840f442e', 'Australia National Waste Policy', 'National Waste Policy', 'The 2018 National Waste Policy provides a framework for collective action by businesses, governments, communities and individuals until 2030. The policy identifies five overarching principles underpinning waste management in a circular economy. These include: Avoid waste; Improve resource recovery; Increase use of recycled material and build demand and markets for recycled products; Better manage material flows to benefit human health, the environment and the economy; Improve information to support innovation, guide investment and enable informed consumer decisions. The 2018 National Waste Policy will guide continuing collaboration between all Australian governments, business and industry. It does not remove the need for governments, businesses and industries to implement tailored solutions in response to local and regional circumstances.', 'The 2018 National Waste Policy provides a framework for collective action by businesses, governments, communities and individuals until 2030. The policy identifies five overarching principles underpinning waste management in a circular economy. These include: Avoid waste; Improve resource recovery; Increase use of recycled material and build demand and markets for recycled products; Better manage material flows to benefit human health, the environment and the economy; Improve information to support innovation, guide investment and enable informed consumer decisions. The 2018 National Waste Policy will guide continuing collaboration between all Australian governments, business and industry. It does not remove the need for governments, businesses and industries to implement tailored solutions in response to local and regional circumstances.', 'The 2018 National Waste Policy provides a framework for collective action by businesses, governments, communities and individuals until 2030. The policy identifies five overarching principles underpinning waste management in a circular economy. These include: Avoid waste; Improve resource recovery; Increase use of recycled material and build demand and markets for recycled products; Better manage material flows to benefit human health, the environment and the economy; Improve information to support innovation, guide investment and enable informed consumer decisions. The 2018 National Waste Policy will guide continuing collaboration between all Australian governments, business and industry. It does not remove the need for governments, businesses and industries to implement tailored solutions in response to local and regional circumstances.', 'Australia', 'climate', 'in_force', '2018-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_36', ARRAY['australia', 'sdg2', 'sdg17', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
