INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9878857-415a-5f0a-997a-27948654be44', 'Australia Integrating sustainability into the procurement process', 'Integrating sustainability into the procurement process, 2018', 'The following guidance document has been developed to assist Queensland Government procurement officers to integrate sustainability considerations into the procurement process. The method of integrating sustainability into each step of procurement process is examined, from contract (arrangement) establishment to contract management.', 'The following guidance document has been developed to assist Queensland Government procurement officers to integrate sustainability considerations into the procurement process. The method of integrating sustainability into each step of procurement process is examined, from contract (arrangement) establishment to contract management.', 'The following guidance document has been developed to assist Queensland Government procurement officers to integrate sustainability considerations into the procurement process. The method of integrating sustainability into each step of procurement process is examined, from contract (arrangement) establishment to contract management.', 'Australia', 'nature', 'in_force', '2018-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_82', ARRAY['australia', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
