INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7717d978-d876-5996-b1b6-09791f30d476', 'Australia FSC Standard 23: Principles of Internal Governance', 'FSC Standard 23: Principles of Internal Governance and Asset Stewardship', 'This Standard has been drafted to provide guidance to FSC Members who undertake the role of Asset Managers in setting and achieving best practice in fulfilling their fiduciary responsibility as custodians of one of the largest pools of managed funds in the world.', 'This Standard has been drafted to provide guidance to FSC Members who undertake the role of Asset Managers in setting and achieving best practice in fulfilling their fiduciary responsibility as custodians of one of the largest pools of managed funds in the world.', 'This Standard has been drafted to provide guidance to FSC Members who undertake the role of Asset Managers in setting and achieving best practice in fulfilling their fiduciary responsibility as custodians of one of the largest pools of managed funds in the world.', 'Australia', 'governance', 'in_force', '2017-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_24', ARRAY['australia', 'voluntary_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e06e62db-25da-52b8-93fe-c55314a1b77c', 'Australia Carbon risk: a burning issue', 'Carbon risk: a burning issue', 'Six specific recommendations are made, including: (1) That the Australian Securities and Investments Commission review its guidance to directors to ensure that it provides a proper understanding of the manifestations of carbon risk, and reflects evolving asset measurement implications of carbon risk. (2) That the Australian Stock Exchange provide guidance regarding the circumstances in which a listed entity''s exposure to carbon risk requires disclosure under Recommendation 7.4 of the Australian Stock Exchange Corporate Governance Principles and Recommendations. (3) That the government nominate a single government entity to have primary responsibility for coordinating the response to the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures. (3) That the government commit to implementing the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures where appropriate, and undertaking the necessary law reform to give them effect. (5) That the government review the Corporations Act 2001 to consider whether the obligations for financial disclosure should require holistic consideration of a company''s prospects, including the viability of its business model. (6) That the government end the uncertainty regarding climate change policy, and develop a stable and consistent policy (such as an emissions intensity scheme for the electricity sector).', 'Six specific recommendations are made, including: (1) That the Australian Securities and Investments Commission review its guidance to directors to ensure that it provides a proper understanding of the manifestations of carbon risk, and reflects evolving asset measurement implications of carbon risk. (2) That the Australian Stock Exchange provide guidance regarding the circumstances in which a listed entity''s exposure to carbon risk requires disclosure under Recommendation 7.4 of the Australian Stock Exchange Corporate Governance Principles and Recommendations. (3) That the government nominate a single government entity to have primary responsibility for coordinating the response to the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures. (3) That the government commit to implementing the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures where appropriate, and undertaking the necessary law reform to give them effect. (5) That the government review the Corporations Act 2001 to consider whether the obligations for financial disclosure should require holistic consideration of a company''s prospects, including the viability of its business model. (6) That the government end the uncertainty regarding climate change policy, and develop a stable and consistent policy (such as an emissions intensity scheme for the electricity sector).', 'Six specific recommendations are made, including: (1) That the Australian Securities and Investments Commission review its guidance to directors to ensure that it provides a proper understanding of the manifestations of carbon risk, and reflects evolving asset measurement implications of carbon risk. (2) That the Australian Stock Exchange provide guidance regarding the circumstances in which a listed entity''s exposure to carbon risk requires disclosure under Recommendation 7.4 of the Australian Stock Exchange Corporate Governance Principles and Recommendations. (3) That the government nominate a single government entity to have primary responsibility for coordinating the response to the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures. (3) That the government commit to implementing the recommendations of the Financial Stability Board Task Force on Climate-related Financial Disclosures where appropriate, and undertaking the necessary law reform to give them effect. (5) That the government review the Corporations Act 2001 to consider whether the obligations for financial disclosure should require holistic consideration of a company''s prospects, including the viability of its business model. (6) That the government end the uncertainty regarding climate change policy, and develop a stable and consistent policy (such as an emissions intensity scheme for the electricity sector).', 'Australia', 'climate', 'in_force', '2017-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_45', ARRAY['australia', 'sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d61f6b50-d059-5d74-93ec-910b5ae26027', 'Australia Environment Protection Act', 'Environment Protection Act, 2017', 'The Act gives EPA enhanced powers and tools to prevent and minimise the risks of harm to human health and the environment from pollution and waste. It also provides EPA with the ability to pursue stronger sanctions and penalties to hold environmental polluters to account.', 'The Act gives EPA enhanced powers and tools to prevent and minimise the risks of harm to human health and the environment from pollution and waste. It also provides EPA with the ability to pursue stronger sanctions and penalties to hold environmental polluters to account.', 'The Act gives EPA enhanced powers and tools to prevent and minimise the risks of harm to human health and the environment from pollution and waste. It also provides EPA with the ability to pursue stronger sanctions and penalties to hold environmental polluters to account.', 'Australia', 'nature', 'in_force', '2017-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_79', ARRAY['australia', 'regulations', 'mandatory', 'sdg12', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6a1d24a3-ef39-508f-b049-318bd2247f0f', 'Australia Public environmental reporting guidelines Guidance for Victorian public', 'Public environmental reporting guidelines Guidance for Victorian public healthcare services, 2017', 'The Environmental reporting guidelines (the guidelines) assist Victorian public health services to publish environmental data, and to promote regular, accurate and consistent reporting of environmental data across the Victorian public healthcare system. Consistency in reporting will allow comparison of environmental performance over time.', 'The Environmental reporting guidelines (the guidelines) assist Victorian public health services to publish environmental data, and to promote regular, accurate and consistent reporting of environmental data across the Victorian public healthcare system. Consistency in reporting will allow comparison of environmental performance over time.', 'The Environmental reporting guidelines (the guidelines) assist Victorian public health services to publish environmental data, and to promote regular, accurate and consistent reporting of environmental data across the Victorian public healthcare system. Consistency in reporting will allow comparison of environmental performance over time.', 'Australia', 'climate', 'in_force', '2017-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_80', ARRAY['australia', 'sdg3', 'guidance_frameworks', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
